from itertools import product
from math import sqrt

def euclidean(a, b):
    return sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def diam_weight(face):
    return max((euclidean(x, y) for x, y in product(face, repeat=2)),
               default=0.0)

def in_vr(face, eps):
    return all(euclidean(x, y) <= eps for x, y in product(face, repeat=2))

square = [(0,0),(1,0),(0,1),(1,1)]
d = diam_weight(square)
print('diamWeight =', round(d, 4))
for eps in (0.9, 1.0, 1.4, 1.5):
    print(eps, in_vr(square, eps), d <= eps)

