function CECH_VERTEX_CENTER(face, eps):       # reverse direction
    for c in face:
        if for all x in face: dist(x,c) <= eps: return c
    return NONE

function FORWARD_CERT(face, center, eps):     # Cech(eps) -> VR(2eps)
    assert for all x in face: dist(x, center) <= eps
    for x in face:
        for y in face:
            assert dist(x,y) <= dist(x,center) + dist(center,y) <= 2*eps
    return 'face in VR(2*eps)'

